// Picks the winning raffle ticket. Two things matter here, both load-bearing
// for trust with parents putting real money into this:
//
// 1. The draw is bounded by tickets actually sold, not the competition's
//    cap — a 500-cap raffle that only sells 250 draws from 1-250, never an
//    unsold number in the 251-500 range.
// 2. The winning number is a deterministic function of a seed generated by
//    the OS's cryptographically secure RNG, not picked independently of it.
//    Reveal the seed alongside the result and anyone can re-run
//    numberFromSeed() themselves and get the same answer — the admin
//    panel has no way to have picked a different number than the seed
//    actually produced.
import crypto from "node:crypto";

export function numberFromSeed(seed: string, ticketsSold: number): number {
  if (ticketsSold < 1) throw new Error("Cannot derive a winning number with zero tickets sold");
  const hash = crypto.createHash("sha256").update(seed).digest();
  const value = hash.readUInt32BE(0);
  // Modulo bias here is on the order of ticketsSold / 2^32 — for any
  // realistic ticket count (thousands, not billions) that's not
  // measurable, so plain modulo is fine rather than rejection sampling.
  return (value % ticketsSold) + 1;
}

export function drawWinningNumber(ticketsSold: number): { winningNumber: number; seed: string } {
  const seed = crypto.randomBytes(32).toString("hex");
  return { winningNumber: numberFromSeed(seed, ticketsSold), seed };
}

export function verifyDraw(seed: string, ticketsSold: number, claimedNumber: number): boolean {
  return numberFromSeed(seed, ticketsSold) === claimedNumber;
}
